(let [read-proc (fn [path] (with-open [r (java.io.RandomAccessFile. path "r")] (let [buffer (byte-array 4096) n (.read r buffer)] (assert (< 0 n 4096) "Empty or oversized proc line") (let [value (String. buffer 0 n java.nio.charset.StandardCharsets/UTF_8)] (assert (clojure.string/ends-with? value "\n") "Incomplete proc line") value)))) boot (clojure.string/trim (read-proc "/proc/sys/kernel/random/boot_id")) stat (read-proc "/proc/self/stat") fields (clojure.string/split (subs stat (+ 2 (.lastIndexOf stat ")"))) #"\s+")] (assert (= boot "b04f7fb6-ea65-4b47-8866-73e24a6887f6")) (assert (= "125503" (nth fields 19))) {:boot-id boot :start-ticks (nth fields 19) :stat-bytes (count stat) :bounded-read-bytes 4096 :guards-pass? true})
